"""Append reviewed, source-specific service/policy/university scenarios.
The expected facts below come from original official pages/PDFs checked in this
research session. They are not generated from chatbot answers.
"""
import argparse,json,re,sqlite3,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser();p.add_argument('--cache',required=True);a=p.parse_args();db=sqlite3.connect(Path(a.cache)/'crawl.sqlite')
f=ROOT/'evals/knowledge-expansion-2026-11-04.json';dataset=json.loads(f.read_text());cases=[c for c in dataset['cases'] if int(c['id'][2:])<=251]
BASE='https://www.uaeu.ac.ae/en/'

def add(q,expected,url,checks,arabic,category,needle,section=None,focus='Missing Knowledge',needs=True):
    source=BASE+url if not url.startswith('https:') else url
    row=db.execute('select result from urls where url=?',(source,)).fetchone()
    if not row:raise ValueError('Undiscovered source '+source)
    raw=json.loads(row[0])
    if raw.get('state')!='fetched':raise ValueError('Unavailable source '+source)
    text=raw.get('text','')
    if section:
        selected=[s['text'] for s in raw.get('sections',[]) if section in s['heading']]
        if not selected:raise ValueError('Missing official source section '+section)
        text='\n'.join(selected)
    normalized=re.sub(r'\s+',' ',text).lower().replace('( ','(').replace(' )',')');target=re.sub(r'\s+',' ',needle).lower().replace('( ','(').replace(' )',')')
    if target not in normalized:raise ValueError('Source does not contain reviewed fact '+needle+' in '+source)
    i=normalized.index(target);quote=normalized[max(0,i-120):i+len(target)+240]
    cases.append({'id':f'KE{len(cases)+1:03}','category':category,'language':'en','focus':focus,'turns':[q],'expected':expected,'sources':[source],'needsCitation':needs,'checks':[{'name':name,'any':patterns if isinstance(patterns,list) else [patterns]} for name,patterns in checks],'variants':[q.replace('What','Please tell me what',1) if q.startswith('What') else 'At UAEU, '+q[0].lower()+q[1:],q.replace('UAEU','United Arab Emirates University') if 'UAEU' in q else 'For a UAEU student: '+q[0].lower()+q[1:],arabic,q+' Please keep the answer focused on this question.'],'sourceQuote':quote,'sourceBodySha256':raw.get('sha256'),'sourceVerified':raw.get('verified'),'reviewRequired':True})

